@startuml

class Airline {
  + id : string
}

class Airport {
  + id : string
}

class Flight {
  + id : string
  + departureTime : datetime
  + arrivalTime : datetime
}

class Aircraft {
  + type : string
  + isWorking : boolean
  + isLanded : boolean
}

class Pilot {
  + experienceLevel : int
}

class AircraftType {
  + name : string
}

class RoleRequirement {
  + role : string
  + requiredCount : int
}

Airline "1" -- "*" Flight
Airline "1" *-- "*" Aircraft
Flight "0..*" -- "1" Airport : departure
Flight "0..*" -- "1" Airport : arrival
Flight "0..*" -- "1" Pilot : captain
Flight "0..*" -- "1" Pilot : co-pilot
Flight "0..*" -- "1" Aircraft
Aircraft "*" -- "1" AircraftType
AircraftType "1" *-- "*" RoleRequirement
Pilot "*" -- "1" Airline

@enduml

